1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} runs. Reads the body once and republishes it for later steps.
14	 */
15	public class ValidateOwnerFields {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
18	            throws OwnerFieldsInvalidException {
19	        List<String> errors = new ArrayList<>();
20	        checkRequired("firstName", request.getFirstName(), errors);
21	        checkRequired("lastName", request.getLastName(), errors);
22	        checkRequired("address", request.getAddress(), errors);
23	        checkRequired("city", request.getCity(), errors);
24	        checkRequired("telephone", request.getTelephone(), errors);
25	        normalizeTelephone(request, errors);
26	        if (!errors.isEmpty()) {
27	            throw new OwnerFieldsInvalidException(errors);
28	        }
29	        validated.set(request);
30	    }
31	
32	    private static void checkRequired(String field, String value, List<String> errors) {
33	        if (value == null || value.isBlank()) {
34	            errors.add(field);
35	        }
36	    }
37	
38	    /**
39	     * Strips every non-digit character from the telephone and requires exactly 10 digits,
40	     * storing the normalized value back on the request so later steps persist and return it.
41	     * Anything other than 10 digits after stripping is a 400 (adds a "telephone" error).
42	     */
43	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
44	        String telephone = request.getTelephone();
45	        if (telephone == null) {
46	            return;
47	        }
48	        String digits = telephone.replaceAll("\\D", "");
49	        if (digits.length() == 10) {
50	            request.setTelephone(digits);
51	        }
52	        else if (!errors.contains("telephone")) {
53	            errors.add("telephone");
54	        }
55	    }
56	}
